import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

RC_PARAMS = {
    "font.size": 9,
    "axes.labelsize": 9,
    "axes.titlesize": 9,
    "xtick.labelsize": 8,
    "ytick.labelsize": 8,
    "legend.fontsize": 8,
    "axes.linewidth": 0.8,
    "xtick.major.width": 0.8,
    "ytick.major.width": 0.8,
}

FIGSIZE = (3.4, 2.6)
PALETTE = ["#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#8C564B", "#000000"]
MUTED = "#bdbdbd"

DATA_PATH = "data/benchmarks.csv"
X_FIELD = "params_m"
Y_FIELD = "accuracy"
STEM = "07-params-trendline"
FORMATS = ["png", "svg", "pdf"]
DPI = 600


def load():
    return pd.read_csv(DATA_PATH)


def add_trendline(ax, xs, ys, colour):
    x = np.asarray(xs, dtype=float)
    y = np.asarray(ys, dtype=float)
    valid = np.isfinite(x) & np.isfinite(y)
    if valid.sum() < 2:
        return
    slope, intercept = np.polyfit(x[valid], y[valid], 1)
    line = np.linspace(x[valid].min(), x[valid].max(), 100)
    ax.plot(line, slope * line + intercept, color=colour, linewidth=1.0, linestyle="--", zorder=1)


def draw(ax, df):
    ax.scatter(df[X_FIELD], df[Y_FIELD], color=PALETTE[0], s=18, zorder=2)
    add_trendline(ax, df[X_FIELD], df[Y_FIELD], PALETTE[0])


def finish(fig, ax):
    ax.set_xlabel("Parameters (M)")
    ax.set_ylabel("Top-1 accuracy (%)")
    ax.grid(False)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    fig.tight_layout()


def main():
    df = load()
    with plt.rc_context(RC_PARAMS):
        fig, ax = plt.subplots(figsize=FIGSIZE)
        draw(ax, df)
        finish(fig, ax)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            kwargs = {"bbox_inches": "tight"}
            if fmt == "png":
                kwargs["dpi"] = DPI
            fig.savefig(path, **kwargs)
            print(f"wrote {path}")
    plt.close(fig)


if __name__ == "__main__":
    main()
